<?php
namespace Core;use Core\CurlSafe;use Core\Site;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class PeoplePhoto{const UA='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';const RETRY_DAYS=7;public static function dir(){$a=Site::uploadDir().'/people';if(!is_dir($a)){@mkdir($a,0755,true);}return $a;}public static function url($a){$a=trim((string)$a);if($a===''||mb_strlen($a)>40||!preg_match('//u',$a)){return'';}$b=md5($a);$c=self::dir().'/'.$b.'.jpg';if(is_file($c)&&@filesize($c)>1024){return'/uisc-assets/people/'.$b.'.jpg';}$d=self::dir().'/'.$b.'.url';if(is_file($d)){$e=trim((string)@file_get_contents($d));if($e!==''){return $e;}}$f=self::dir().'/'.$b.'.nof';if(is_file($f)&&(time()-(int)@filemtime($f))<self::RETRY_DAYS*86400){return'';}$g=self::baikeImage($a);if($g!==''&&self::download($g,$c)){return'/uisc-assets/people/'.$b.'.jpg';}$g=self::baiduImageSearch($a);if($g!==''&&self::download($g,$c)){return'/uisc-assets/people/'.$b.'.jpg';}$h=self::tmdbPersonImage($a);if($h!==''){@file_put_contents($d,$h,LOCK_EX);return $h;}@file_put_contents($f,(string)time(),LOCK_EX);return'';}private static function baikeImage($a){foreach(array($a,$a.' 演员')as $b){$c='https://baike.baidu.com/api/openapi/BaikeLemmaCardApi'.'?scope=103&format=json&appid=379020&bk_length=600&bk_key='.rawurlencode($b);$d=array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>8,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_HTTPHEADER=>array('User-Agent: '.self::UA,'Referer: https://baike.baidu.com/','Accept: application/json',),);$e=CurlSafe::request($c,$d,8);if($e['err']!==''){continue;}$f=json_decode((string)$e['body'],true);if(!is_array($f)||empty($f['image'])||!is_string($f['image'])){continue;}if(strpos($f['image'],'http')!==0){continue;}return $f['image'];}return'';}private static function baiduImageSearch($a){$b='https://image.baidu.com/search/acjson?tn=resultjson_com&ipn=rj&ct=201326592'.'&fp=result&word='.rawurlencode($a).'&queryWord='.rawurlencode($a).'&cl=2&lm=-1&ie=utf-8&oe=utf-8&pn=0&rn=10';$c=array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>8,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_HTTPHEADER=>array('User-Agent: '.self::UA,'Referer: https://image.baidu.com/','Accept: application/json',),);$d=CurlSafe::request($b,$c,8);if($d['err']!==''){return'';}$e=(string)$d['body'];$f=json_decode($e,true);$g=(is_array($f)&&!empty($f['data'])&&is_array($f['data']))?$f['data']:array();if(!$g&&preg_match_all('/"thumbURL":"(https?:\/\/[^"]+)"/',$e,$h)){foreach($h[1]as $i){$g[]=array('thumbURL'=>$i);}}foreach($g as $j){if(!is_array($j)||empty($j['thumbURL'])||!is_string($j['thumbURL'])){continue;}$i=$j['thumbURL'];if(strpos($i,'http')!==0){continue;}$k=isset($j['width'])?(int)$j['width']:0;$l=isset($j['height'])?(int)$j['height']:0;if($k>0&&$l>0&&$k>500&&$l<$k){continue;}if(stripos($i,'.gif')!==false){continue;}return $i;}return'';}private static function tmdbPersonImage($a){$b=trim((string)Config::sub('tmdb','api_key',''));if($b===''){return'';}$c='https://api.themoviedb.org/3/search/person?query='.rawurlencode($a).'&api_key='.rawurlencode($b).'&language=zh-CN&page=1';$d=array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>8,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_HTTPHEADER=>array('User-Agent: '.self::UA,'Accept: application/json'),);$e=CurlSafe::request($c,$d,8);if($e['err']!==''){return'';}$f=json_decode((string)$e['body'],true);if(!is_array($f)||empty($f['results'])||!is_array($f['results'])){return'';}foreach($f['results']as $g){if(is_array($g)&&!empty($g['profile_path'])&&is_string($g['profile_path'])){return'https://image.tmdb.org/t/p/w185'.$g['profile_path'];}}return'';}private static function download($a,$b){$c=array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>12,CURLOPT_CONNECTTIMEOUT=>6,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_HTTPHEADER=>array('User-Agent: '.self::UA,'Referer: https://baike.baidu.com/',),);$d=CurlSafe::request($a,$c,12);if($d['err']!==''||(int)$d['code']!==200){return false;}$e=(string)$d['body'];if(strlen($e)<2048||strlen($e)>8*1024*1024){return false;}$f=(substr($e,0,3)==="\xFF\xD8\xFF");$g=(substr($e,0,8)==="\x89PNG\r\n\x1a\n");$h=(substr($e,0,4)==='RIFF'&&substr($e,8,4)==='WEBP');if(!$f&&!$g&&!$h){return false;}return@file_put_contents($b,$e,LOCK_EX)!==false;}}